// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceApiUrlResolver {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceApiUrlResolver] = [UniffiVTableCallbackInterfaceApiUrlResolver(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeApiUrlResolver.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface ApiUrlResolver: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeApiUrlResolver.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface ApiUrlResolver: handle missing in uniffiClone")
            }
        },
        resolve: { (
            uniffiHandle: UInt64,
            namespace: RustBuffer,
            endpointSegments: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<UInt64>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> ParsedUrl in
                guard let uniffiObj = try? FfiConverterTypeApiUrlResolver.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.resolve(
                     namespace: try FfiConverterString.lift(namespace),
                     endpointSegments: try FfiConverterSequenceString.lift(endpointSegments)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeParsedUrl_lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )]
}

private func uniffiCallbackInitApiUrlResolver() {
    uniffi_wp_api_fn_init_callback_vtable_apiurlresolver(UniffiCallbackInterfaceApiUrlResolver.vtable)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeApiUrlResolver: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<ApiUrlResolver>()

    typealias FfiType = UInt64
    typealias SwiftType = ApiUrlResolver

    public static func lift(_ handle: UInt64) throws -> ApiUrlResolver {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ApiUrlResolverImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: ApiUrlResolver) -> UInt64 {
         if let rustImpl = value as? ApiUrlResolverImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ApiUrlResolver {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ApiUrlResolver, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


