// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceWpApiMiddleware {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceWpApiMiddleware] = [UniffiVTableCallbackInterfaceWpApiMiddleware(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeWpApiMiddleware.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface WpApiMiddleware: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeWpApiMiddleware.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface WpApiMiddleware: handle missing in uniffiClone")
            }
        },
        process: { (
            uniffiHandle: UInt64,
            requestExecutor: UInt64,
            response: RustBuffer,
            request: UInt64,
            context: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> WpNetworkResponse in
                guard let uniffiObj = try? FfiConverterTypeWpApiMiddleware.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.process(
                     requestExecutor: try FfiConverterTypeRequestExecutor_lift(requestExecutor),
                     response: try FfiConverterTypeWpNetworkResponse_lift(response),
                     request: try FfiConverterTypeWpNetworkRequest_lift(request),
                     context: try FfiConverterOptionTypeRequestContext.lift(context)
                )
            }

            let uniffiHandleSuccess = { (returnValue: WpNetworkResponse) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypeWpNetworkResponse_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeRequestExecutionError_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )]
}

private func uniffiCallbackInitWpApiMiddleware() {
    uniffi_wp_api_fn_init_callback_vtable_wpapimiddleware(UniffiCallbackInterfaceWpApiMiddleware.vtable)
}

