public enum ApplicationPasswordsNotSupportedReason: Equatable, Hashable {
    
    case applicationPasswordBlockedByPlugin(plugin: KnownAuthenticationBlockingPlugin
    )
    case applicationPasswordBlockedByMultiplePlugins
    case siteIsLocalDevelopmentEnvironment
    case applicationPasswordsDisabledForHttpSite





}

