    typealias SwiftType = ApplicationPasswordsNotSupportedReason

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ApplicationPasswordsNotSupportedReason {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .applicationPasswordBlockedByPlugin(plugin: try FfiConverterTypeKnownAuthenticationBlockingPlugin.read(from: &buf)
        )
        
        case 2: return .applicationPasswordBlockedByMultiplePlugins
        
        case 3: return .siteIsLocalDevelopmentEnvironment
        
        case 4: return .applicationPasswordsDisabledForHttpSite
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ApplicationPasswordsNotSupportedReason, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .applicationPasswordBlockedByPlugin(plugin):
            writeInt(&buf, Int32(1))
            FfiConverterTypeKnownAuthenticationBlockingPlugin.write(plugin, into: &buf)
            
        
        case .applicationPasswordBlockedByMultiplePlugins:
            writeInt(&buf, Int32(2))
        
        
        case .siteIsLocalDevelopmentEnvironment:
            writeInt(&buf, Int32(3))
        
        
        case .applicationPasswordsDisabledForHttpSite:
            writeInt(&buf, Int32(4))
        
        }
    }
}


