    )
    case RequestExecutionFailed(statusCode: UInt16?, redirects: [WpRedirect]?, reason: RequestExecutionErrorReason, requestUrl: String, requestMethod: RequestMethod
    )
    case MediaFileNotFound(filePath: String
    )
    case ResponseParsingError(reason: String, response: String, requestUrl: String, requestMethod: RequestMethod
    )
    case SiteUrlParsingError(reason: String
    )
    case UnknownError(statusCode: UInt16, response: String, requestUrl: String, requestMethod: RequestMethod
    )
    case WpError(errorCode: WpErrorCode, errorMessage: String, statusCode: UInt16, response: String, requestUrl: String, requestMethod: RequestMethod
    )

    

    

    
}

