        case 1: return .InvalidHttpStatusCode(
            statusCode: try FfiConverterUInt16.read(from: &buf), 
            requestUrl: try FfiConverterString.read(from: &buf), 
            requestMethod: try FfiConverterTypeRequestMethod.read(from: &buf)
            )
        case 2: return .RequestExecutionFailed(
            statusCode: try FfiConverterOptionUInt16.read(from: &buf), 
            redirects: try FfiConverterOptionSequenceTypeWpRedirect.read(from: &buf), 
            reason: try FfiConverterTypeRequestExecutionErrorReason.read(from: &buf), 
            requestUrl: try FfiConverterString.read(from: &buf), 
            requestMethod: try FfiConverterTypeRequestMethod.read(from: &buf)
            )
        case 3: return .MediaFileNotFound(
            filePath: try FfiConverterString.read(from: &buf)
            )
        case 4: return .ResponseParsingError(
            reason: try FfiConverterString.read(from: &buf), 
            response: try FfiConverterString.read(from: &buf), 
            requestUrl: try FfiConverterString.read(from: &buf), 
            requestMethod: try FfiConverterTypeRequestMethod.read(from: &buf)
            )
        case 5: return .SiteUrlParsingError(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .UnknownError(
            statusCode: try FfiConverterUInt16.read(from: &buf), 
            response: try FfiConverterString.read(from: &buf), 
            requestUrl: try FfiConverterString.read(from: &buf), 
            requestMethod: try FfiConverterTypeRequestMethod.read(from: &buf)
            )
        case 7: return .WpError(
            errorCode: try FfiConverterTypeWpErrorCode.read(from: &buf), 
            errorMessage: try FfiConverterString.read(from: &buf), 
            statusCode: try FfiConverterUInt16.read(from: &buf), 
            response: try FfiConverterString.read(from: &buf), 
